/**
 * Supported audio container formats (UI-020).
 *
 * The empty state advertises exactly this list (GUI_UX_SPEC §3:
 * WAV・MP3・FLAC・M4A・OGG), so detection is extension-based and honest —
 * anything outside the list gets the actionable 対応していない形式 error
 * instead of a decoder shrug. Keep in sync with
 * `AUDIO_EXTENSIONS` in src-tauri/src/lib.rs (the read command allowlist).
 */
import type { AudioFormat } from "./types";

export const AUDIO_EXTENSIONS: readonly AudioFormat[] = [
  "wav",
  "mp3",
  "flac",
  "m4a",
  "ogg",
];

/** HornScribe project document suffix (project schema v1, FND-001). */
export const PROJECT_FILE_SUFFIX = ".hornscribe.json";

/** Lowercase extension without the dot ("" when absent). */
export function fileExtension(name: string): string {
  const base = baseName(name);
  const dot = base.lastIndexOf(".");
  if (dot <= 0 || dot === base.length - 1) return "";
  return base.slice(dot + 1).toLowerCase();
}

/** Detect the audio format from a file name; null when unsupported. */
export function audioFormatOf(name: string): AudioFormat | null {
  const ext = fileExtension(name);
  return (AUDIO_EXTENSIONS as readonly string[]).includes(ext)
    ? (ext as AudioFormat)
    : null;
}

/** Basename for both `/` and `\` separators (Windows paths). */
export function baseName(path: string): string {
  const norm = path.replace(/\\/g, "/");
  const idx = norm.lastIndexOf("/");
  return idx === -1 ? norm : norm.slice(idx + 1);
}

/** Display name for a project file: basename minus .hornscribe.json. */
export function projectDisplayName(path: string): string {
  const base = baseName(path);
  return base.toLowerCase().endsWith(PROJECT_FILE_SUFFIX)
    ? base.slice(0, base.length - PROJECT_FILE_SUFFIX.length)
    : base;
}

/**
 * MediaElementTransport tests (UI-020 adapter over the UI-004 contract).
 * A FakePort stands in for HTMLAudioElement — the adapter's state machine,
 * snapshot emission and loop/seek/rate rules are what get asserted.
 */

import { describe, expect, it, vi } from "vitest";
import {
  MediaElementTransport,
  MIN_LOOP_SECONDS,
  type MediaPort,
  type MediaPortHandlers,
  type TransportSnapshot,
} from "./mediaTransport";
import type { MediaSource } from "./types";

class FakePort implements MediaPort {
  time = 0;
  duration = 120;
  rate = 1;
  preservePitch = true;
  playing = false;
  loaded: MediaSource | null = null;
  seekCalls: number[] = [];
  failLoad = false;
  private handlers = new Set<MediaPortHandlers>();

  async load(source: MediaSource): Promise<void> {
    if (this.failLoad) throw new Error("load failed");
    this.loaded = source;
  }
  async play(): Promise<void> {
    this.playing = true;
  }
  pause(): void {
    this.playing = false;
  }
  seekTo(seconds: number): void {
    this.time = seconds;
    this.seekCalls.push(seconds);
  }
  setRate(rate: number): void {
    this.rate = rate;
  }
  setPreservePitch(on: boolean): void {
    this.preservePitch = on;
  }
  getTime(): number {
    return this.time;
  }
  getDuration(): number {
    return this.duration;
  }
  subscribe(handlers: MediaPortHandlers): () => void {
    this.handlers.add(handlers);
    return () => this.handlers.delete(handlers);
  }
  emit(key: keyof MediaPortHandlers): void {
    for (const h of this.handlers) h[key]?.();
  }
}

function makeTransport(failLoad = false) {
  const port = new FakePort();
  port.failLoad = failLoad;
  const transport = new MediaElementTransport(port);
  const snaps: TransportSnapshot[] = [];
  transport.subscribe((s) => snaps.push(s));
  return { port, transport, snaps };
}

const SRC: MediaSource = { kind: "blob", blob: new Blob(["x"]) };

describe("load", () => {
  it("empty → loading → ready with snapshots on each step", async () => {
    const { transport, snaps } = makeTransport();
    await transport.load(SRC);
    expect(transport.getSnapshot().status).toBe("ready");
    expect(snaps.map((s) => s.status)).toEqual(["loading", "ready"]);
  });

  it("a failed load flips to error and rejects", async () => {
    const { transport, snaps } = makeTransport(true);
    await expect(transport.load(SRC)).rejects.toThrow();
    expect(transport.getSnapshot().status).toBe("error");
    expect(snaps.map((s) => s.status)).toEqual(["loading", "error"]);
  });
});

describe("play / pause / stop / ended", () => {
  it("play → playing; pause → paused; play after ended rewinds first", async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    await transport.play();
    expect(transport.getSnapshot().status).toBe("playing");

    transport.pause();
    expect(transport.getSnapshot().status).toBe("paused");

    // `ended` only fires while playing (a paused element never ends).
    await transport.play();
    port.time = 42;
    port.emit("onEnded");
    expect(transport.getSnapshot().status).toBe("ended");

    await transport.play();
    expect(port.seekCalls.at(-1)).toBe(0); // rewind before replay
    expect(transport.getSnapshot().status).toBe("playing");
  });

  it("stop pauses and seeks to 0 (loop start when armed)", async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    await transport.play();
    transport.setLoop({ start: 10, end: 20 });
    port.time = 15;
    transport.stop();
    expect(port.playing).toBe(false);
    expect(port.time).toBe(10);
    expect(transport.getSnapshot().status).toBe("ready");
  });

  it("no-ops while empty/loading (no source yet)", async () => {
    const { transport } = makeTransport();
    await transport.play(); // status empty — silently ignored
    transport.pause();
    transport.stop();
    expect(transport.getSnapshot().status).toBe("empty");
  });
});

describe("seek / rate / loop", () => {
  it("seek clamps into [0, duration] and unsticks 'ended'", async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    await transport.play();
    port.emit("onEnded");
    await transport.seek(50);
    expect(port.time).toBe(50);
    expect(transport.getSnapshot().status).toBe("paused");
    await transport.seek(999);
    expect(port.time).toBe(120);
    await transport.seek(-3);
    expect(port.time).toBe(0);
  });

  it("setRate clamps to [0.25, 4] and emits", async () => {
    const { port, transport } = makeTransport();
    transport.setRate(2);
    expect(port.rate).toBe(2);
    transport.setRate(0.01);
    expect(port.rate).toBe(0.25);
    transport.setRate(99);
    expect(port.rate).toBe(4);
  });

  it("setLoop validates the range and clears on null", async () => {
    const { transport } = makeTransport();
    await transport.load(SRC);
    transport.setLoop({ start: 5, end: 5 + MIN_LOOP_SECONDS / 2 });
    expect(transport.getSnapshot().loop).toBeNull(); // too short → rejected
    transport.setLoop({ start: 5, end: 30 });
    expect(transport.getSnapshot().loop).toEqual({ start: 5, end: 30 });
    transport.setLoop(null);
    expect(transport.getSnapshot().loop).toBeNull();
  });

  it("playback past loop.end wraps to loop.start (A-B via media seek)", async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    await transport.play();
    transport.setLoop({ start: 10, end: 20 });
    port.time = 20.5;
    port.emit("onTimeUpdate");
    expect(port.seekCalls.at(-1)).toBe(10);
  });

  it("load clears a previously armed loop", async () => {
    const { transport } = makeTransport();
    await transport.load(SRC);
    transport.setLoop({ start: 1, end: 2 });
    await transport.load(SRC);
    expect(transport.getSnapshot().loop).toBeNull();
  });
});

describe("snapshots / listeners", () => {
  it("revision bumps per emit; time mirrors the audio clock", async () => {
    const { port, transport, snaps } = makeTransport();
    await transport.load(SRC);
    port.time = 33;
    port.emit("onTimeUpdate");
    const last = snaps.at(-1)!;
    expect(last.time).toBe(33);
    expect(last.revision).toBe(snaps.length);
    expect(last.duration).toBe(120);
  });

  it("unsubscribe stops notifications; dispose pauses the port", async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    const spy = vi.fn();
    const off = transport.subscribe(spy);
    transport.pause();
    transport.setRate(1.5);
    expect(spy).toHaveBeenCalled();
    off();
    const calls = spy.mock.calls.length;
    transport.setRate(1.25);
    expect(spy.mock.calls.length).toBe(calls);

    await transport.play();
    transport.dispose();
    expect(port.playing).toBe(false);
  });
});

/**
 * Minimal TransportController adapter for the AUDIO_READY state (UI-020),
 * consistent with the UI-004 spike contract
 * (apps/spikes/waveform/src/transport/types.ts).
 *
 * HornScribe owns this contract: the HTMLMediaElement is an adapter behind
 * `MediaPort`, the audio clock (`getCurrentTime`) is authoritative, and
 * snapshots are emitted to subscribers on state changes and media
 * timeupdate ticks (media-element cadence ≈4 Hz — no rAF, no 60 Hz
 * React churn; the full UI-004 pipeline with its rAF pump/Regions lands
 * with the real waveform view).
 *
 * A-B loop semantics mirror the spike: `[start, end)` wraps via a media
 * seek, which costs a small audible gap — the documented MediaElement
 * constraint, accepted here for the import-stage adapter.
 */
import type { MediaSource } from "./types";

export type TransportStatus =
  | "empty"
  | "loading"
  | "ready"
  | "playing"
  | "paused"
  | "ended"
  | "error";

/** Half-open time range in seconds: [start, end). */
export interface TimeRange {
  start: number;
  end: number;
}

export interface TransportSnapshot {
  status: TransportStatus;
  /** Audio-clock time in seconds (low-frequency mirror; use getCurrentTime
      for per-frame reads). */
  time: number;
  duration: number;
  rate: number;
  loop: TimeRange | null;
  /** Monotonic counter bumped on every emitted snapshot. */
  revision: number;
}

export type TransportListener = (snapshot: TransportSnapshot) => void;
export type Unsubscribe = () => void;

export const MIN_RATE = 0.25;
export const MAX_RATE = 4;
export const SUPPORTED_RATES = [0.5, 0.75, 1, 1.25, 1.5] as const;
/** Loops shorter than this are rejected (noise-level accidental drags). */
export const MIN_LOOP_SECONDS = 0.01;

/** Event feed the port must surface to the adapter. */
export interface MediaPortHandlers {
  onTimeUpdate?(): void;
  onEnded?(): void;
  onError?(): void;
}

/**
 * The media backend seam (UI-004 spike naming). `load` resolves when the
 * source is decoded enough to report a duration and accept play().
 */
export interface MediaPort {
  load(source: MediaSource): Promise<void>;
  play(): Promise<void>;
  pause(): void;
  seekTo(seconds: number): void;
  setRate(rate: number): void;
  setPreservePitch(on: boolean): void;
  getTime(): number;
  getDuration(): number;
  subscribe(handlers: MediaPortHandlers): Unsubscribe;
}

/* ---------------------- HTMLAudioElement backend ---------------------- */

class AudioElementMediaPort implements MediaPort {
  private readonly el: HTMLAudioElement;
  private objectUrl: string | null = null;
  private readonly handlers = new Set<MediaPortHandlers>();

  constructor(el?: HTMLAudioElement) {
    this.el = el ?? new Audio();
    this.el.preload = "auto";
    this.el.addEventListener("timeupdate", () => this.emit("onTimeUpdate"));
    this.el.addEventListener("ended", () => this.emit("onEnded"));
    this.el.addEventListener("error", () => this.emit("onError"));
  }

  private emit(key: keyof MediaPortHandlers) {
    for (const h of this.handlers) h[key]?.();
  }

  load(source: MediaSource): Promise<void> {
    this.revoke();
    const url =
      source.kind === "url"
        ? source.url
        : ((this.objectUrl = URL.createObjectURL(source.blob)), this.objectUrl);
    return new Promise<void>((resolve, reject) => {
      const cleanup = () => {
        this.el.removeEventListener("loadedmetadata", ok);
        this.el.removeEventListener("error", ng);
      };
      const ok = () => {
        cleanup();
        resolve();
      };
      const ng = () => {
        cleanup();
        reject(new Error("media element could not load the source"));
      };
      this.el.addEventListener("loadedmetadata", ok, { once: true });
      this.el.addEventListener("error", ng, { once: true });
      this.el.src = url;
    });
  }

  private revoke() {
    if (this.objectUrl) {
      URL.revokeObjectURL(this.objectUrl);
      this.objectUrl = null;
    }
  }

  play(): Promise<void> {
    return this.el.play();
  }
  pause(): void {
    this.el.pause();
  }
  seekTo(seconds: number): void {
    this.el.currentTime = seconds;
  }
  setRate(rate: number): void {
    this.el.playbackRate = rate;
  }
  setPreservePitch(on: boolean): void {
    // Set the standard property plus the historical vendor-prefixed ones —
    // engines ignore the names they do not implement.
    const el = this.el as HTMLAudioElement & {
      mozPreservesPitch?: boolean;
      webkitPreservesPitch?: boolean;
    };
    el.preservesPitch = on;
    el.mozPreservesPitch = on;
    el.webkitPreservesPitch = on;
  }
  getTime(): number {
    return this.el.currentTime;
  }
  getDuration(): number {
    return Number.isFinite(this.el.duration) ? this.el.duration : 0;
  }
  subscribe(handlers: MediaPortHandlers): Unsubscribe {
    this.handlers.add(handlers);
    return () => this.handlers.delete(handlers);
  }
}

/* ------------------------------ controller ------------------------------ */

export class MediaElementTransport {
  private readonly port: MediaPort;
  private status: TransportStatus = "empty";
  private rate = 1;
  private loop: TimeRange | null = null;
  private revision = 0;
  private readonly listeners = new Set<TransportListener>();

  constructor(port?: MediaPort) {
    this.port = port ?? new AudioElementMediaPort();
    this.port.subscribe({
      onTimeUpdate: () => {
        if (this.status === "playing" && this.loop) {
          const t = this.port.getTime();
          if (t >= this.loop.end) {
            // A-B wrap via media seek — see doc header for the known
            // ~60 ms MediaElement gap measured in the UI-004 spike.
            this.port.seekTo(this.loop.start);
          }
        }
        this.emit();
      },
      onEnded: () => {
        if (this.status === "playing") {
          this.status = "ended";
          this.emit();
        }
      },
      onError: () => {
        if (this.status !== "empty") {
          this.status = "error";
          this.emit();
        }
      },
    });
  }

  /** Load a source. Resolves when ready to play; rejects → status "error". */
  async load(source: MediaSource): Promise<void> {
    this.status = "loading";
    this.loop = null;
    this.emit();
    try {
      await this.port.load(source);
      this.status = "ready";
    } catch (e) {
      this.status = "error";
      this.emit();
      throw e;
    }
    this.emit();
  }

  async play(): Promise<void> {
    if (this.status === "empty" || this.status === "loading") return;
    if (this.status === "ended") this.port.seekTo(0);
    if (this.status === "playing") return;
    await this.port.play();
    this.status = "playing";
    this.emit();
  }

  pause(): void {
    if (this.status !== "playing") return;
    this.port.pause();
    this.status = "paused";
    this.emit();
  }

  /** Pause and return to t=0 (or the loop start when a loop is armed). */
  stop(): void {
    if (this.status === "empty" || this.status === "loading") return;
    this.port.pause();
    this.port.seekTo(this.loop?.start ?? 0);
    this.status = "ready";
    this.emit();
  }

  /** Seek to an absolute position in seconds, clamped to [0, duration]. */
  async seek(seconds: number): Promise<void> {
    const duration = this.port.getDuration();
    const target = Math.min(Math.max(seconds, 0), duration);
    this.port.seekTo(target);
    if (this.status === "ended") this.status = "paused";
    this.emit();
  }

  /** Playback rate, clamped to [MIN_RATE, MAX_RATE]. */
  setRate(rate: number): void {
    this.rate = Math.min(MAX_RATE, Math.max(MIN_RATE, rate));
    this.port.setRate(this.rate);
    this.emit();
  }

  /** Request pitch preservation for rate != 1 (backend permitting). */
  setPreservePitch(on: boolean): void {
    this.port.setPreservePitch(on);
    this.emit();
  }

  /** Arm (TimeRange) or clear (null) the A-B loop. Degenerate/inverted
      ranges and ranges past the media end are rejected (clamped). */
  setLoop(range: TimeRange | null): void {
    if (range === null) {
      this.loop = null;
      this.emit();
      return;
    }
    const duration = this.port.getDuration();
    const start = Math.max(0, range.start);
    const end = Math.min(duration, range.end);
    if (end - start < MIN_LOOP_SECONDS) return;
    this.loop = { start, end };
    this.emit();
  }

  /** Authoritative audio-clock time — read on demand. */
  getCurrentTime(): number {
    return this.port.getTime();
  }
  getDuration(): number {
    return this.port.getDuration();
  }

  getSnapshot(): TransportSnapshot {
    return {
      status: this.status,
      time: this.port.getTime(),
      duration: this.port.getDuration(),
      rate: this.rate,
      loop: this.loop ? { ...this.loop } : null,
      revision: this.revision,
    };
  }

  subscribe(listener: TransportListener): Unsubscribe {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  dispose(): void {
    this.listeners.clear();
    this.port.pause();
  }

  private emit(): void {
    this.revision += 1;
    const snap = this.getSnapshot();
    for (const l of this.listeners) l(snap);
  }
}

/**
 * Native file drop (UI-020; GUI_UX_SPEC §3 "ドロップ → 音源読込").
 *
 * With `dragDropEnabled: true` (tauri.conf.json) the webview does NOT get
 * HTML5 drop events — Tauri intercepts them and emits `onDragDropEvent`
 * payloads carrying real filesystem paths. In plain-browser dev the HTML5
 * drop on the score region supplies `File` objects instead, and this
 * listener resolves to a no-op (same degrade pattern as tauri/bridge.ts).
 */
import { getCurrentWindow } from "@tauri-apps/api/window";

export interface NativeDropPayload {
  type: "enter" | "over" | "drop" | "leave";
  /** Dropped file paths (present on enter/over/drop). */
  paths: string[];
}

/**
 * Subscribe to the window drag-drop stream. `cb` receives every payload so
 * the caller can drive both the drop affordance (enter/over/leave) and the
 * import itself (drop). Resolves to an unsubscribe (identity no-op outside
 * the Tauri webview).
 */
export async function listenNativeDrop(
  cb: (payload: NativeDropPayload) => void,
): Promise<() => void> {
  try {
    const unlisten = await getCurrentWindow().onDragDropEvent((event) => {
      const p = event.payload;
      cb({ type: p.type, paths: "paths" in p ? p.paths : [] });
    });
    return unlisten;
  } catch {
    return () => undefined;
  }
}

/**
 * Import ports — the typed seams between the import controller and its
 * environment (UI-020; mirrors the port/adapter style used by the UI-004
 * TransportController contract).
 *
 * `ImportController` depends only on this interface, so tests drive fake
 * ports and the production wiring (`runtimePorts.ts`) selects Tauri IPC or
 * browser fallbacks per capability — never by sniffing in the controller.
 */
import type { AudioFileRef } from "./types";

/** Result of decoding audio for display (waveform + metadata). */
export interface DecodedAudio {
  durationSeconds: number;
  sampleRate: number;
  /** Normalized peak amplitudes 0–1. */
  peaks: readonly number[];
}

/** Thrown by `decodeAudio` when the bytes cannot be decoded — the
 *  controller maps it to the recoverable `openFailed` issue. */
export class AudioDecodeError extends Error {
  constructor(message = "decodeAudioData failed") {
    super(message);
    this.name = "AudioDecodeError";
  }
}

export interface ImportPorts {
  /**
   * Show the file picker (Tauri dialog plugin; `<input type=file>` in
   * browser dev). Resolves null when the user cancels — cancel is not an
   * error and never surfaces copy.
   */
  pickAudio(): Promise<AudioFileRef | null>;
  /** Bytes of a `kind:"path"` ref (Rust `read_audio_bytes` command). */
  readAudioBytes(path: string): Promise<Blob>;
  /** Bytes of a `.hornscribe.json` project file (`read_project_file`). */
  readProjectBytes(path: string): Promise<Blob>;
  /** Decode audio for the waveform/metadata (WebAudio decodeAudioData). */
  decodeAudio(blob: Blob, fileName: string): Promise<DecodedAudio>;
  /**
   * SHA-256 of file contents as lowercase hex — the same contract as
   * `hash_file_sha256` in python/hornscribe/project/model.py, so relink
   * verification matches `ProjectStore.relink_source_audio`.
   */
  sha256Hex(blob: Blob): Promise<string>;
}

/**
 * Recent-projects MRU tests (UI-020 / GUI_UX_SPEC §3). Storage is injected
 * so the list logic runs without a DOM; failures degrade to empty/in-memory.
 */

import { describe, expect, it } from "vitest";
import {
  MAX_RECENT_PROJECTS,
  loadRecentProjects,
  recordRecentProject,
  removeRecentProject,
} from "./recentProjects";

/** Map-backed Storage stub (getItem/setItem only — all the module uses). */
function memStorage(seed?: Record<string, string>) {
  const map = new Map<string, string>(Object.entries(seed ?? {}));
  return {
    getItem: (k: string) => map.get(k) ?? null,
    setItem: (k: string, v: string) => void map.set(k, v),
    map,
  };
}

const KEY = "hornscribe.recentProjects.v1";

describe("loadRecentProjects", () => {
  it("returns [] with no storage", () => {
    expect(loadRecentProjects(null)).toEqual([]);
  });

  it("returns [] on corrupt JSON instead of throwing", () => {
    const s = memStorage({ [KEY]: "{not json" });
    expect(loadRecentProjects(s)).toEqual([]);
  });

  it("drops malformed entries and sorts newest-first", () => {
    const s = memStorage({
      [KEY]: JSON.stringify([
        { name: "old", path: "/p/old", openedAt: 1 },
        { bogus: true },
        { name: "new", path: "/p/new", openedAt: 9 },
        { name: "mid", path: "/p/mid", openedAt: 5 },
      ]),
    });
    expect(loadRecentProjects(s).map((e) => e.name)).toEqual([
      "new",
      "mid",
      "old",
    ]);
  });
});

describe("recordRecentProject", () => {
  it("unshifts the entry and persists it", () => {
    const s = memStorage();
    const list = recordRecentProject({ name: "a", path: "/p/a" }, s, 100);
    expect(list[0]).toEqual({ name: "a", path: "/p/a", openedAt: 100 });
    expect(loadRecentProjects(s)[0]?.path).toBe("/p/a");
  });

  it("dedupes by path and bumps openedAt", () => {
    const s = memStorage();
    recordRecentProject({ name: "a", path: "/p/a" }, s, 100);
    recordRecentProject({ name: "b", path: "/p/b" }, s, 200);
    const list = recordRecentProject({ name: "a2", path: "/p/a" }, s, 300);
    expect(list.map((e) => e.path)).toEqual(["/p/a", "/p/b"]);
    expect(list[0]).toMatchObject({ name: "a2", openedAt: 300 });
  });

  it("caps the list at MAX_RECENT_PROJECTS", () => {
    const s = memStorage();
    for (let i = 0; i < MAX_RECENT_PROJECTS + 3; i++) {
      recordRecentProject({ name: `p${i}`, path: `/p/${i}` }, s, i);
    }
    const list = loadRecentProjects(s);
    expect(list).toHaveLength(MAX_RECENT_PROJECTS);
    expect(list[0]?.path).toBe(`/p/${MAX_RECENT_PROJECTS + 2}`);
  });
});

describe("removeRecentProject", () => {
  it("removes by path and persists", () => {
    const s = memStorage();
    recordRecentProject({ name: "a", path: "/p/a" }, s, 1);
    recordRecentProject({ name: "b", path: "/p/b" }, s, 2);
    const list = removeRecentProject("/p/a", s);
    expect(list.map((e) => e.path)).toEqual(["/p/b"]);
    expect(loadRecentProjects(s).map((e) => e.path)).toEqual(["/p/b"]);
  });
});

/**
 * 最近使ったプロジェクト (GUI_UX_SPEC §3: shown only when history exists).
 *
 * localStorage-backed MRU of `.hornscribe.json` files. Entries are recorded
 * on successful project opens; a failed open keeps the entry (the error UX
 * — e.g. SOURCE_MISSING relink — is where the user decides what to do).
 * Best-effort: storage failures degrade to an in-memory list.
 */
import type { RecentProjectEntry } from "./types";

const STORAGE_KEY = "hornscribe.recentProjects.v1";
export const MAX_RECENT_PROJECTS = 8;

function isEntry(v: unknown): v is RecentProjectEntry {
  return (
    typeof v === "object" &&
    v !== null &&
    typeof (v as RecentProjectEntry).name === "string" &&
    typeof (v as RecentProjectEntry).path === "string" &&
    typeof (v as RecentProjectEntry).openedAt === "number"
  );
}

export function loadRecentProjects(
  storage: Pick<Storage, "getItem"> | null = defaultStorage(),
): RecentProjectEntry[] {
  if (!storage) return [];
  try {
    const raw = storage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as unknown;
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter(isEntry)
      .sort((a, b) => b.openedAt - a.openedAt)
      .slice(0, MAX_RECENT_PROJECTS);
  } catch {
    return [];
  }
}

/**
 * Insert/touch `path` as the most-recent entry, deduped by path, capped at
 * MAX_RECENT_PROJECTS. Returns the updated list (also persisted).
 */
export function recordRecentProject(
  entry: { name: string; path: string },
  storage: Pick<Storage, "getItem" | "setItem"> | null = defaultStorage(),
  now = Date.now(),
): RecentProjectEntry[] {
  const list = loadRecentProjects(storage).filter((e) => e.path !== entry.path);
  list.unshift({ ...entry, openedAt: now });
  const capped = list.slice(0, MAX_RECENT_PROJECTS);
  persist(capped, storage);
  return capped;
}

/** Drop a path (e.g. user removes a dead entry later on). */
export function removeRecentProject(
  path: string,
  storage: Pick<Storage, "getItem" | "setItem"> | null = defaultStorage(),
): RecentProjectEntry[] {
  const list = loadRecentProjects(storage).filter((e) => e.path !== path);
  persist(list, storage);
  return list;
}

function persist(
  list: RecentProjectEntry[],
  storage: Pick<Storage, "setItem"> | null,
): void {
  try {
    storage?.setItem(STORAGE_KEY, JSON.stringify(list));
  } catch {
    /* persistence is best-effort */
  }
}

function defaultStorage(): Storage | null {
  try {
    return typeof window !== "undefined" ? window.localStorage : null;
  } catch {
    return null;
  }
}

/**
 * Production ImportPorts (UI-020).
 *
 * Environment matrix:
 * - Tauri webview: native open dialog via @tauri-apps/plugin-dialog
 *   (capability `dialog:allow-open` — the only plugin grant; no fs/asset
 *   protocol), file bytes via the self-limited `read_audio_bytes` /
 *   `read_project_file` commands (extension allowlist + size cap in Rust).
 * - Plain-browser dev (`vite dev`): `<input type=file>` picker and
 *   File-object drops — bytes come straight from the File, and the
 *   path-only ports throw (they are unreachable in that mode anyway).
 *
 * Every port degrades instead of throwing where a fallback exists, so the
 * shell keeps rendering in a bare browser session.
 */
import { invoke } from "@tauri-apps/api/core";
import { open as openDialog } from "@tauri-apps/plugin-dialog";
import { ja } from "../strings/ja";
import { AUDIO_EXTENSIONS, baseName } from "./formats";
import {
  AudioDecodeError,
  type DecodedAudio,
  type ImportPorts,
} from "./ports";
import type { AudioFileRef } from "./types";

/** True inside the Tauri webview (the IPC bridge is injected). */
function isTauri(): boolean {
  return (
    typeof window !== "undefined" && "__TAURI_INTERNALS__" in window
  );
}

/* ------------------------------ file picker ------------------------------ */

async function pickViaDialog(): Promise<AudioFileRef | null> {
  const selected = await openDialog({
    multiple: false,
    directory: false,
    filters: [
      {
        name: ja.import.dialog.audioFilter,
        extensions: [...AUDIO_EXTENSIONS],
      },
      // An escape hatch so the "unsupported format" recovery path stays
      // reachable through the dialog, not only through drag&drop.
      { name: ja.import.dialog.allFiles, extensions: ["*"] },
    ],
  });
  if (typeof selected !== "string" || selected === "") return null;
  return { kind: "path", path: selected, name: baseName(selected) };
}

/**
 * Browser-dev fallback picker. `cancel` is observable on Chrome-family
 * browsers; the window-focus timer covers engines without the event.
 */
function pickViaFileInput(): Promise<AudioFileRef | null> {
  return new Promise((resolve) => {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = AUDIO_EXTENSIONS.map((e) => `.${e}`).join(",");
    let settled = false;
    const done = (ref: AudioFileRef | null) => {
      if (settled) return;
      settled = true;
      resolve(ref);
    };
    input.addEventListener("change", () => {
      const file = input.files?.[0] ?? null;
      done(file ? { kind: "file", file, name: file.name } : null);
    });
    input.addEventListener("cancel", () => done(null));
    // Focus returning without a change event ≈ cancel (Safari/older engines).
    const onFocus = () => setTimeout(() => done(null), 400);
    window.addEventListener("focus", onFocus, { once: true });
    input.click();
  });
}

/* ------------------------------- raw bytes ------------------------------- */

/** Tauri returns binary IPC payloads as ArrayBuffer/Uint8Array; the JSON
 *  fallback is a number[] — normalize all three into a fresh
 *  `Uint8Array<ArrayBuffer>` (a view over a SharedArrayBuffer is not a
 *  valid BlobPart under the typed-array generics). */
function toUint8(data: unknown): Uint8Array<ArrayBuffer> {
  if (data instanceof ArrayBuffer) return new Uint8Array(data);
  if (ArrayBuffer.isView(data)) {
    // Copy: `data.buffer` is ArrayBufferLike — copying guarantees a plain
    // ArrayBuffer for the Blob constructor.
    return new Uint8Array(
      new Uint8Array(data.buffer, data.byteOffset, data.byteLength),
    );
  }
  if (Array.isArray(data)) return new Uint8Array(data as number[]);
  throw new Error("unexpected binary IPC payload");
}

async function invokeBytes(command: string, path: string): Promise<Blob> {
  const raw = await invoke<unknown>(command, { path });
  return new Blob([toUint8(raw)]);
}

/* ------------------------------- decoding -------------------------------- */

const PEAK_BUCKETS = 600;

let sharedAudioContext: AudioContext | null = null;

/** Merge all channels into |peak| buckets for the waveform strip. */
export function computePeaks(buffer: AudioBuffer, buckets = PEAK_BUCKETS): number[] {
  const length = buffer.length;
  const channels = buffer.numberOfChannels;
  const peaks = new Array<number>(buckets).fill(0);
  if (length === 0 || channels === 0) return peaks;
  const per = Math.max(1, Math.floor(length / buckets));
  for (let c = 0; c < channels; c++) {
    const data = buffer.getChannelData(c);
    for (let b = 0; b < buckets; b++) {
      const start = b * per;
      const end = Math.min(start + per, length);
      let peak = peaks[b];
      for (let i = start; i < end; i++) {
        const v = Math.abs(data[i]);
        if (v > peak) peak = v;
      }
      peaks[b] = peak;
    }
  }
  return peaks;
}

async function decodeWithWebAudio(blob: Blob): Promise<DecodedAudio> {
  const Ctor: typeof AudioContext | undefined =
    globalThis.AudioContext ??
    (globalThis as { webkitAudioContext?: typeof AudioContext })
      .webkitAudioContext;
  if (!Ctor) {
    // Headless/test environments — decoding is unavailable, not "bad file".
    throw new AudioDecodeError("AudioContext unavailable");
  }
  sharedAudioContext ??= new Ctor();
  const raw = await blob.arrayBuffer();
  let buffer: AudioBuffer;
  try {
    buffer = await sharedAudioContext.decodeAudioData(raw);
  } catch (e) {
    throw new AudioDecodeError(
      e instanceof Error ? e.message : "decodeAudioData failed",
    );
  }
  return {
    durationSeconds: buffer.duration,
    sampleRate: buffer.sampleRate,
    peaks: computePeaks(buffer),
  };
}

async function sha256Hex(blob: Blob): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    await blob.arrayBuffer(),
  );
  return [...new Uint8Array(digest)]
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

/* ------------------------------ composition ------------------------------ */

export function createImportPorts(): ImportPorts {
  return {
    pickAudio: () => (isTauri() ? pickViaDialog() : pickViaFileInput()),
    readAudioBytes: (path) => invokeBytes("read_audio_bytes", path),
    readProjectBytes: (path) => invokeBytes("read_project_file", path),
    decodeAudio: (blob) => decodeWithWebAudio(blob),
    sha256Hex,
  };
}

/**
 * Import domain types (issue #25 / UI-020; docs/GUI_UX_SPEC.md §3/§4/§20).
 *
 * The import flow turns a user-picked file into a `LoadedAudio` the shell
 * can draw (waveform peaks + metadata) and play (UI-004 TransportController
 * contract media source), or into a recoverable `ImportIssue` rendered with
 * the copy-deck error shape (what failed / what is kept / next action).
 */

/** Advertised container formats (GUI_UX_SPEC §3: WAV・MP3・FLAC・M4A・OGG). */
export type AudioFormat = "wav" | "mp3" | "flac" | "m4a" | "ogg";

/**
 * A user-selected audio file. Inside Tauri the native dialog and the
 * window drag-drop event hand us real filesystem paths; in plain-browser
 * dev sessions the HTML drop/file-input hands us `File` objects.
 */
export type AudioFileRef =
  | { kind: "path"; path: string; name: string }
  | { kind: "file"; file: File; name: string };

/**
 * What the UI-004 TransportController contract can load — mirrors the
 * spike's `AudioSource` (url | blob). We always hand over a blob: either
 * the dropped `File` itself or a Blob built from `read_audio_bytes`, so the
 * user-owned source file is only ever read, never modified.
 */
export type MediaSource = { kind: "url"; url: string } | { kind: "blob"; blob: Blob };

/** Fully decoded audio ready for the AUDIO_READY state (GUI_UX_SPEC §4). */
export interface LoadedAudio {
  /** Where the bytes came from (kept for relink/re-open bookkeeping). */
  ref: AudioFileRef;
  fileName: string;
  format: AudioFormat;
  sizeBytes: number;
  /** Audio-clock duration in seconds (0 while unknown). */
  durationSeconds: number;
  sampleRate: number;
  /** Normalized peak amplitudes 0–1 for the waveform strip. */
  peaks: readonly number[];
  /** Playback-ready source for the transport adapter. */
  mediaSource: MediaSource;
}

/**
 * Recoverable import failures — every variant has a copy-deck title/body
 * plus a recovery action, so errors never dead-end (acceptance: "invalid
 * file has actionable Japanese error", "unsupported codec does not
 * dead-end").
 */
export type ImportIssue =
  /** Extension is not in the advertised set — honest format guidance. */
  | { kind: "unsupported"; fileName: string }
  /** Read/decode failed (corrupt file, vanished path, codec the webview
      cannot decode and FFmpeg normalization has not landed yet). */
  | { kind: "openFailed"; fileName?: string }
  /** `.hornscribe.json` could not be read or parsed. */
  | { kind: "projectOpenFailed"; fileName: string };

/**
 * The subset of `HornScribeProject` (python/hornscribe/project/model.py,
 * schema v1) the relink UX needs. `sourcePath`/`sourceHash` mirror
 * `sourceAudio.originalPath` / `contentHash`.
 */
export interface ProjectSummary {
  /** Absolute path of the .hornscribe.json file itself. */
  path: string;
  projectId: string;
  /** Display name — file basename without the .hornscribe.json suffix. */
  name: string;
  sourcePath: string | null;
  sourceHash: string | null;
}

/** SOURCE_MISSING context: which project lost its audio, and whether the
 *  last relink candidate failed the content-hash check (deck:
 *  sourceMoved vs sourceHashMismatch copy). */
export interface SourceMissingInfo {
  project: ProjectSummary;
  mismatch: boolean;
}

/** A "最近使ったプロジェクト" entry (GUI_UX_SPEC §3). */
export interface RecentProjectEntry {
  name: string;
  path: string;
  /** Epoch ms of the last successful open (sorting + pruning). */
  openedAt: number;
}

/**
 * 採譜オプション (GUI_UX_SPEC §4 advanced options — hidden in the popover
 * next to 採譜を開始). Values are option keys; Japanese labels resolve via
 * ja.import.audioOptions. Consumed by the transcription feature (UI-040),
 * persisted nowhere yet.
 */
export interface TranscriptionOptions {
  tempo: "auto" | "manual";
  tempoBpm: number | null;
  meter: string;
  minDuration: string;
  triplets: "auto" | "allow" | "none";
  simplicity: "standard" | "simple" | "detailed";
  range: "all" | "selection";
}

export const DEFAULT_TRANSCRIPTION_OPTIONS: TranscriptionOptions = {
  tempo: "auto",
  tempoBpm: null,
  meter: "4/4",
  minDuration: "16",
  triplets: "auto",
  simplicity: "standard",
  range: "all",
};

/**
 * HornScribe app shell layout + token consumers.
 * Colors come only from --hs-* semantic tokens (tokens.css).
 */

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--hs-font-family);
  font-size: var(--hs-font-size-body);
  color: var(--hs-text-primary);
  background: var(--hs-surface-app);
  overflow: hidden;
}

/* UI-009 latent bug, fixed for the real shell (UI-011): FluentProvider
   renders a wrapper div between #root and the shell; without a definite
   height the `height:100%` grid below collapsed to content height. */
.hs-provider {
  height: 100%;
}

/* ---- Visible keyboard focus (DESIGN_SYSTEM §16) ----
   2px+, distinct from adjacent surface; Fluent v9 components draw their own
   compatible focus ring, this guarantees the same contract for every other
   focusable region (waveform, score surface, segmented control, links). */
:focus-visible {
  outline: var(--hs-focus-width) solid var(--hs-focus);
  outline-offset: var(--hs-focus-offset);
  border-radius: var(--hs-radius-input);
}
/* Never remove the outline without a replacement. */
:focus:not(:focus-visible) {
  outline: none;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ============================ App shell ============================ */
/* GUI_UX_SPEC §2 information architecture:
   title bar → command bar → waveform → score workspace → transport → status */
.hs-shell {
  display: grid;
  grid-template-rows: auto auto auto minmax(0, 1fr) auto auto;
  grid-template-areas:
    "titlebar"
    "commandbar"
    "waveform"
    "main"
    "transport"
    "statusbar";
  height: 100%;
  min-width: 0;
  /* §21: <1100px is unsupported — the native window minimum (1100×640 in
     tauri.conf.json) stops resizing first; this floor mirrors it so a
     browser dev viewport can never compress the layout below spec. With
     body overflow:hidden the excess clips instead of scrolling — there is
     deliberately no app-level horizontal scroll. */
  min-width: 1100px;
  min-height: 640px;
  background: var(--hs-surface-app);
  color: var(--hs-text-primary);
}

/* ---- Title bar area (in-app; native window chrome is kept) ---- */
.hs-titlebar {
  grid-area: titlebar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 32px;
  padding: 0 var(--hs-space-ms);
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-secondary);
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  user-select: none;
}
.hs-titlebar__app {
  font-weight: 600;
  color: var(--hs-text-primary);
}
.hs-titlebar__doc {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---- Command bar (DESIGN_SYSTEM §10: ~44px, never scrolls) ---- */
.hs-commandbar {
  grid-area: commandbar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 44px;
  padding: 0 var(--hs-space-ms);
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  overflow: hidden;
  white-space: nowrap;
}
/* Buttons never shrink/clip — below 1600px secondary labels hide instead
   (§21 icon化), below 1200px 設定 moves to the overflow menu. */
.hs-commandbar .fui-ToolbarButton,
.hs-commandbar .fui-Button {
  flex-shrink: 0;
}
/* 1200–1599px: secondary commands render icon-only; their Tooltip carries
   the full Japanese label (§24). Labels are hidden, never ellipsized. */
@media (max-width: 1599px) {
  .hs-commandbar__label {
    display: none;
  }
}
.hs-commandbar__spacer {
  flex: 1 1 auto;
  min-width: var(--hs-space-sm);
}

/* ---- Segmented control (DESIGN_SYSTEM §11: text labels, never icon-only) ---- */
.hs-segmented {
  display: inline-flex;
  flex: 0 0 auto;
  border: 1px solid var(--hs-border-strong);
  border-radius: var(--hs-radius-input);
  overflow: hidden;
  background: var(--hs-surface-elevated);
}
.hs-segmented__item {
  appearance: none;
  border: none;
  background: transparent;
  color: var(--hs-text-secondary);
  font-family: var(--hs-font-family);
  font-size: var(--hs-font-size-compact);
  line-height: 1;
  padding: 8px 12px;
  cursor: pointer;
  white-space: nowrap;
}
.hs-segmented__item + .hs-segmented__item {
  border-left: 1px solid var(--hs-border-subtle);
}
.hs-segmented__item:hover {
  background: var(--hs-control-hover);
}
/* selected state = fill + weight + border cues combined (§11);
   on-accent text color keeps ≥4.5:1 in both themes (dark accent is light,
   so the foreground flips to dark ink via --hs-accent-foreground). */
.hs-segmented__item[aria-checked="true"] {
  background: var(--hs-accent);
  color: var(--hs-accent-foreground);
  font-weight: var(--hs-font-weight-emphasis);
  box-shadow: inset 0 0 0 1px var(--hs-accent-pressed);
}
.hs-segmented__item:focus-visible {
  outline-offset: -2px;
}

/* ---- Waveform region (GUI_UX_SPEC §8: 96–120px standard) ----
   Height is inline (user-resizable via the bottom-edge separator);
   min/max here are the CSS backstop, JS clamps are authoritative. */
.hs-waveform {
  grid-area: waveform;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 64px;
  max-height: 35vh;
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-compact);
}
.hs-waveform__resizer {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -4px;
  height: 8px;
  cursor: row-resize;
  touch-action: none;
  z-index: 6;
}

/* Decoded peaks (UI-020): one stroked <path> keeps the strip cheap to
   repaint — bars are 1px columns centred on the midline (§8). */
.hs-waveform__peaks {
  position: absolute;
  inset: 4px 0 6px;
  width: 100%;
  height: calc(100% - 10px);
  color: var(--hs-accent);
  pointer-events: none;
}
.hs-waveform__peaks path {
  stroke: currentColor;
  stroke-width: 0.8;
  vector-effect: non-scaling-stroke;
}
.hs-waveform__playhead {
  position: absolute;
  top: 0;
  bottom: 6px;
  width: 1px;
  background: var(--hs-status-error);
  pointer-events: none;
}
.hs-waveform__name {
  position: absolute;
  right: var(--hs-space-sm);
  top: var(--hs-space-xs);
  max-width: 40%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-caption);
  pointer-events: none;
}
.hs-waveform__placeholder {
  pointer-events: none;
}

/* Shared separator affordance: quiet until hover/focus (§8 elevation —
   workspace stays flat, so the grip uses a translucent accent wash). */
.hs-waveform__resizer:hover,
.hs-waveform__resizer:focus-visible,
.hs-properties__resizer:hover,
.hs-properties__resizer:focus-visible {
  background: color-mix(in srgb, var(--hs-accent) 30%, transparent);
}

/* ---- Score workspace + properties ---- */
.hs-main {
  grid-area: main;
  position: relative; /* anchor for the overlay properties drawer */
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  min-height: 0;
  min-width: 0;
}

.hs-score {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--hs-space-md);
  min-width: 0;
  min-height: 0;
  padding: var(--hs-space-lg);
  background: var(--hs-surface-score);
  color: var(--hs-text-primary);
  /* Score paper keeps a hairline radius, not decorative rounding (§7). */
  border-radius: var(--hs-radius-score-paper);
  overflow: auto;
}
.hs-score--dragover {
  outline: 2px dashed var(--hs-accent);
  outline-offset: -8px;
}
.hs-score__empty-title {
  margin: 0;
  font-size: var(--hs-font-size-title);
  font-weight: 400;
  color: var(--hs-text-primary);
}
/* Score-ready placeholder paper: bounded page shape inside the score
   surface until UI-003 renders real notation. */
.hs-score-paper {
  display: flex;
  align-items: center;
  justify-content: center;
  align-self: stretch;
  flex: 1 1 auto;
  min-height: 0;
  margin: var(--hs-space-xs);
  border: 1px solid var(--hs-score-paper-border);
  border-radius: var(--hs-radius-score-paper);
  background: var(--hs-surface-score);
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-compact);
}

/* Properties inspector (§6, §21): docked at ≥1200px with an inline width
   inside the breakpoint clamp; <1200px it becomes a non-modal overlay
   drawer so the score keeps the workspace. */
.hs-properties {
  position: relative;
  display: flex;
  flex-direction: row;
  min-width: 0;
  min-height: 0;
  background: var(--hs-surface-panel);
  border-left: 1px solid var(--hs-border-subtle);
  color: var(--hs-text-secondary);
}
.hs-properties--overlay {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  z-index: 8;
  background: var(--hs-surface-elevated);
  box-shadow: var(--hs-elevation-sheet);
}
.hs-properties__frame {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
}
.hs-properties__header {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  min-height: 40px;
  padding: var(--hs-space-xs) var(--hs-space-sm) var(--hs-space-xs)
    var(--hs-space-md);
  border-bottom: 1px solid var(--hs-border-subtle);
}
.hs-properties__title {
  flex: 1 1 auto;
  margin: 0;
  font-size: var(--hs-font-size-subtitle);
  font-weight: 600;
  color: var(--hs-text-primary);
}
.hs-properties__body {
  flex: 1 1 auto;
  min-height: 0;
  padding: var(--hs-space-md);
  overflow: auto;
}
.hs-properties__placeholder {
  margin: 0;
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-muted);
}
.hs-properties__resizer {
  position: absolute;
  top: 0;
  bottom: 0;
  left: -5px;
  width: 9px;
  cursor: col-resize;
  touch-action: none;
  z-index: 6;
}
/* Panel open/close motion (§25 panel tier; reduced-motion collapses it). */
@keyframes hs-panel-in {
  from {
    transform: translateX(12px);
    opacity: 0;
  }
  to {
    transform: none;
    opacity: 1;
  }
}
.hs-properties {
  animation: hs-panel-in var(--hs-motion-panel) var(--hs-ease-decelerate);
}

/* ---- Empty state (GUI_UX_SPEC §3, §19: compact, clear CTA) ---- */
.hs-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--hs-space-sm);
  text-align: center;
  max-width: 46em;
}
.hs-empty__title {
  margin: 0;
  font-size: var(--hs-font-size-display);
  font-weight: 400;
}
.hs-empty__or {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-caption);
}
.hs-empty__formats {
  margin: var(--hs-space-xs) 0 0;
  color: var(--hs-text-secondary);
  font-size: var(--hs-font-size-compact);
}
.hs-empty__privacy {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-caption);
}

/* 最近使ったプロジェクト (§3: rendered only when history exists) — a quiet
   list under the CTA, never competing with the primary action. */
.hs-recent {
  margin-top: var(--hs-space-lg);
  padding-top: var(--hs-space-md);
  border-top: 1px solid var(--hs-border-subtle);
  width: 100%;
  max-width: 320px;
}
.hs-recent__title {
  margin: 0 0 var(--hs-space-xs);
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-caption);
  font-weight: var(--hs-font-weight-emphasis);
}
.hs-recent__list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: var(--hs-space-micro);
}
.hs-recent__item {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  width: 100%;
  padding: var(--hs-space-xs) var(--hs-space-sm);
  border: 0;
  border-radius: var(--hs-radius-input);
  background: transparent;
  color: var(--hs-text-secondary);
  font: inherit;
  font-size: var(--hs-font-size-compact);
  cursor: pointer;
  text-align: left;
}
.hs-recent__item:hover {
  background: var(--hs-control-hover);
}
.hs-recent__item:active {
  background: var(--hs-control-pressed);
}
.hs-recent__name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* OPENING_AUDIO (§5): the indeterminate bar + filename sit in the same
   centered column as the empty state so the transition is a text swap. */
.hs-opening {
  gap: var(--hs-space-md);
}
.hs-opening__title {
  margin: 0;
  font-size: var(--hs-font-size-subtitle);
  color: var(--hs-text-primary);
}
.hs-opening__progress {
  width: 100%;
  max-width: 320px;
}
.hs-opening__name {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-caption);
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* AUDIO_READY (§4): metadata line + primary 採譜を開始 with the options
   popover beside it — advanced settings stay hidden by default. */
.hs-audio-ready__meta {
  margin: 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--hs-space-xs);
  color: var(--hs-text-secondary);
  font-size: var(--hs-font-size-compact);
}
.hs-audio-ready__name {
  font-weight: var(--hs-font-weight-emphasis);
  color: var(--hs-text-primary);
}
.hs-audio-ready__actions {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  margin-top: var(--hs-space-sm);
}
.hs-audio-options {
  display: flex;
  flex-direction: column;
  gap: var(--hs-space-sm);
  min-width: 240px;
  padding: var(--hs-space-sm);
}
.hs-audio-options__title {
  margin: 0;
  font-size: var(--hs-font-size-subtitle);
  font-weight: var(--hs-font-weight-title);
}

/* Error cards (§20 AUDIO_ERROR / SOURCE_MISSING): what failed, what is
   kept, the next action — always a recovery path, never a dead end. */
.hs-error {
  gap: var(--hs-space-sm);
  max-width: 40em;
}
.hs-error__icon {
  font-size: 28px;
  color: var(--hs-status-error);
}
.hs-error__title {
  margin: 0;
  font-size: var(--hs-font-size-subtitle);
  font-weight: var(--hs-font-weight-title);
}
.hs-error__file {
  margin: 0;
  color: var(--hs-text-secondary);
  font-size: var(--hs-font-size-compact);
  font-variant-numeric: tabular-nums;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hs-error__body {
  margin: 0;
  color: var(--hs-text-secondary);
  font-size: var(--hs-font-size-compact);
  line-height: var(--hs-line-height-body);
}
.hs-error__actions {
  display: flex;
  gap: var(--hs-space-sm);
  margin-top: var(--hs-space-sm);
}

/* ---- Transport (GUI_UX_SPEC §9) ---- */
.hs-transport {
  grid-area: transport;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 52px;
  padding: 0 var(--hs-space-ms);
  background: var(--hs-surface-panel);
  border-top: 1px solid var(--hs-border-subtle);
}
.hs-transport__time {
  font-variant-numeric: tabular-nums; /* §5: timecode uses tabular numerals */
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-secondary);
  margin-left: var(--hs-space-sm);
  white-space: nowrap;
}
.hs-transport__spacer {
  flex: 1 1 auto;
}

/* ---- Status bar ---- */
.hs-statusbar {
  grid-area: statusbar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-md);
  height: 26px;
  padding: 0 var(--hs-space-ms);
  font-size: var(--hs-font-size-caption);
  color: var(--hs-text-muted);
  background: var(--hs-surface-panel);
  border-top: 1px solid var(--hs-border-subtle);
  user-select: none;
}
.hs-statusbar__message {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hs-statusbar__spacer {
  flex: 1 1 auto;
}

/* ====================== Primitives (components/primitives) ======================
   Only --hs-* semantic tokens; raw values live exclusively in tokens.css. */

/* ---- HsButton (§9): danger re-tints the primary fill to palette red ----
   Double-class selectors keep precedence over Fluent's atomic classes. */
.hs-button.hs-button--danger:not(:disabled) {
  background-color: var(--hs-danger);
  color: var(--hs-danger-foreground);
  border-color: transparent;
}
.hs-button.hs-button--danger:not(:disabled):hover {
  background-color: var(--hs-danger-hover);
}
.hs-button.hs-button--danger:not(:disabled):active {
  background-color: var(--hs-danger-pressed);
}
/* State changes use the fast motion tier (§18). */
.hs-button {
  transition-duration: var(--hs-motion-fast);
  transition-timing-function: var(--hs-ease-standard);
}

/* ---- Segmented control additions (§11, §17) ---- */
.hs-segmented__item:disabled {
  color: var(--hs-text-disabled);
  cursor: not-allowed;
}
.hs-segmented__item:disabled:hover {
  background: transparent;
}
.hs-segmented__item {
  transition: background-color var(--hs-motion-fast) var(--hs-ease-standard);
}

/* ---- StatusBadge / ReviewBadge (§15): tint + glyph + (review) dotted cue ---- */
.hs-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--hs-space-xs);
  padding: 1px var(--hs-space-sm);
  border-radius: var(--hs-radius-input);
  border: 1px solid transparent;
  font-size: var(--hs-font-size-caption);
  line-height: var(--hs-line-height-caption);
  font-weight: var(--hs-font-weight-emphasis);
  white-space: nowrap;
  user-select: none;
}
.hs-badge__icon {
  display: inline-flex;
  font-size: 14px;
}
.hs-badge--neutral {
  color: var(--hs-text-secondary);
  background: var(--hs-status-neutral-subtle);
  border-color: color-mix(in srgb, currentColor 25%, transparent);
}
.hs-badge--info {
  color: var(--hs-status-info);
  background: var(--hs-status-info-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
.hs-badge--success {
  color: var(--hs-status-success);
  background: var(--hs-status-success-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
.hs-badge--warning {
  color: var(--hs-status-warning);
  background: var(--hs-status-warning-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
.hs-badge--error {
  color: var(--hs-status-error);
  background: var(--hs-status-error-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
/* §15: the 要確認 marker adds a dotted underline — review is never red. */
.hs-badge--needs-review .hs-badge__label {
  border-bottom: 2px dotted var(--hs-review-marker);
}

/* ---- HsPanel (§8): flat separation by border; elevated for floats ---- */
.hs-panel {
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: var(--hs-surface-panel);
  border: 1px solid var(--hs-border-subtle);
  border-radius: var(--hs-radius-panel);
  color: var(--hs-text-primary);
}
.hs-panel--elevated {
  background: var(--hs-surface-elevated);
  box-shadow: var(--hs-elevation-popover);
}
.hs-panel__header {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  padding: var(--hs-space-sm) var(--hs-space-ms);
  border-bottom: 1px solid var(--hs-border-subtle);
  min-height: 40px;
}
.hs-panel__title {
  margin: 0;
  font-size: var(--hs-font-size-subtitle);
  line-height: var(--hs-line-height-subtitle);
  font-weight: var(--hs-font-weight-title);
}
.hs-panel__header-spacer {
  flex: 1 1 auto;
}
.hs-panel__body {
  padding: var(--hs-space-md);
  min-width: 0;
}
.hs-panel__body--flush {
  padding: 0;
}

/* ---- HsSlider: track + tabular readout (§5) ---- */
.hs-slider {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
}
.hs-slider .fui-Slider {
  flex: 1 1 auto;
}
.hs-slider__value {
  flex: 0 0 auto;
  min-width: 3.5em;
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-size: var(--hs-font-size-compact);
  line-height: var(--hs-line-height-compact);
  color: var(--hs-text-secondary);
}

/* ---- Settings (auxiliary screen, §18): replaces the workspace rows ---- */
.hs-settings-wrap {
  grid-row: commandbar / transport; /* spans commandbar…main rows */
  display: flex;
  min-height: 0;
  min-width: 0;
}
.hs-settings {
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  padding: var(--hs-space-lg);
  background: var(--hs-surface-app);
  overflow: auto;
}
.hs-settings__title {
  margin: 0 0 var(--hs-space-md);
  font-size: var(--hs-font-size-title);
  font-weight: 600;
}
/* Section chrome (border / radius / padding) comes from the HsPanel
   primitive; this class only constrains width and rhythm. */
.hs-settings__section {
  margin: 0 0 var(--hs-space-lg);
  max-width: 560px;
}
.hs-settings__note {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-compact);
}

/* ============================ UI-040: 採譜中 ============================
   Transcribing body (GUI_UX_SPEC §5) — lives inside the score region;
   not a modal, so the rest of the shell stays usable. */

/* Screen-reader-only text (aria-live announcements, a11y §24). */
.hs-visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.hs-transcribing {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: var(--hs-space-md);
  width: min(420px, 100%);
  text-align: left;
}
.hs-transcribing__title {
  margin: 0;
  font-size: var(--hs-font-size-title);
  font-weight: var(--hs-font-weight-title);
  text-align: center;
}
.hs-transcribing__meta {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--hs-space-md);
  margin-top: calc(-1 * var(--hs-space-sm));
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-secondary);
}
.hs-transcribing__percent {
  font-variant-numeric: tabular-nums;
  font-weight: var(--hs-font-weight-emphasis);
}
.hs-transcribing__elapsed {
  font-variant-numeric: tabular-nums;
}
.hs-transcribing__note {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-caption);
}
/* The HsProgress field stretches inside the transcribing column. */
.hs-transcribing .hs-field {
  width: 100%;
}
.hs-transcribing > .hs-button {
  align-self: center;
}

/* Stage list — pending ○ / active ● / done ✓. The glyph is one cue of
   three (also weight + color), never color alone (§24). */
.hs-stage-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--hs-space-xs);
  font-size: var(--hs-font-size-body);
}
.hs-stage-list__item {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  color: var(--hs-text-muted);
  line-height: var(--hs-line-height-body);
}
.hs-stage-list__icon {
  display: inline-flex;
  width: 1.2em;
  justify-content: center;
  color: var(--hs-text-muted);
}
.hs-stage-list__item[data-state="done"] {
  color: var(--hs-text-secondary);
}
.hs-stage-list__item[data-state="done"] .hs-stage-list__icon {
  color: var(--hs-status-success);
}
.hs-stage-list__item[data-state="active"] {
  color: var(--hs-text-primary);
  font-weight: var(--hs-font-weight-emphasis);
}
.hs-stage-list__item[data-state="active"] .hs-stage-list__icon {
  color: var(--hs-accent);
}

/* ---- §20 error surface (TRANSCRIPTION_ERROR) ---- */
.hs-error-surface {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--hs-space-sm);
  max-width: 46em;
  padding: var(--hs-space-lg);
  background: var(--hs-surface-elevated);
  border: 1px solid var(--hs-border-subtle);
  border-radius: var(--hs-radius-panel);
}
.hs-error-surface__title {
  margin: 0;
  font-size: var(--hs-font-size-title);
  font-weight: var(--hs-font-weight-title);
  color: var(--hs-text-primary);
}
.hs-error-surface__body {
  margin: 0;
  color: var(--hs-text-secondary);
  font-size: var(--hs-font-size-body);
  line-height: var(--hs-line-height-body);
}
.hs-error-surface__actions {
  display: flex;
  gap: var(--hs-space-sm);
  margin-top: var(--hs-space-sm);
  flex-wrap: wrap;
}

/* 診断情報 dialog body — machine detail lives here, never in the surface. */
.hs-diagnostics {
  margin: 0;
  max-height: 40vh;
  overflow: auto;
  white-space: pre-wrap;
  word-break: break-all;
  font-family: ui-monospace, Consolas, monospace;
  font-size: var(--hs-font-size-caption);
  color: var(--hs-text-secondary);
  user-select: text;
}

/**
 * Screen-state machine mapping tests (GUI_UX_SPEC §27; UI-020 added
 * openingAudio / audioError / sourceMissing). Asserts which regions and
 * command gates each state produces so shells/features cannot drift.
 */

import { describe, expect, it } from "vitest";
import {
  SCREEN_STATES,
  commandStateFor,
  hasWorkspaceRegions,
  regionVisibility,
  type ScreenState,
} from "./screen";

const ALL: readonly ScreenState[] = SCREEN_STATES;

describe("SCREEN_STATES", () => {
  it("contains the five UI-020 import states plus the score-side ones", () => {
    for (const s of [
      "empty",
      "openingAudio",
      "audioReady",
      "audioError",
      "sourceMissing",
    ]) {
      expect(ALL).toContain(s);
    }
  });
});

describe("hasWorkspaceRegions", () => {
  it("is false only for empty and the two full-card error states", () => {
    expect(hasWorkspaceRegions("empty")).toBe(false);
    expect(hasWorkspaceRegions("audioError")).toBe(false);
    expect(hasWorkspaceRegions("sourceMissing")).toBe(false);
    // OPENING_AUDIO already mounts the waveform strip (loading line).
    expect(hasWorkspaceRegions("openingAudio")).toBe(true);
    expect(hasWorkspaceRegions("audioReady")).toBe(true);
    expect(hasWorkspaceRegions("transcribing")).toBe(true);
    expect(hasWorkspaceRegions("scoreReady")).toBe(true);
  });
});

describe("regionVisibility", () => {
  it("empty hides waveform/transport/properties", () => {
    const v = regionVisibility("empty");
    expect(v).toMatchObject({
      waveform: false,
      score: true,
      properties: false,
      transport: false,
    });
  });

  it("openingAudio shows the waveform but not transport/properties", () => {
    const v = regionVisibility("openingAudio");
    expect(v).toMatchObject({
      waveform: true,
      properties: false,
      transport: false,
    });
  });

  it("audioReady+ mounts everything", () => {
    for (const s of ["audioReady", "transcribing", "scoreReady"] as const) {
      const v = regionVisibility(s);
      expect(v.waveform).toBe(true);
      expect(v.transport).toBe(true);
      expect(v.properties).toBe(true);
    }
  });

  it("error states mount only the score region", () => {
    for (const s of ["audioError", "sourceMissing"] as const) {
      const v = regionVisibility(s);
      expect(v.score).toBe(true);
      expect(v.waveform).toBe(false);
      expect(v.transport).toBe(false);
      expect(v.properties).toBe(false);
    }
  });
});

describe("commandStateFor", () => {
  it("hasAudio is false for empty/openingAudio and the error states", () => {
    for (const s of [
      "empty",
      "openingAudio",
      "audioError",
      "sourceMissing",
    ] as const) {
      expect(commandStateFor(s).hasAudio).toBe(false);
    }
    expect(commandStateFor("audioReady").hasAudio).toBe(true);
    expect(commandStateFor("transcribing").hasAudio).toBe(true);
  });

  it("isTranscribing only during transcribing; hasScore from scoreReady on", () => {
    expect(commandStateFor("transcribing").isTranscribing).toBe(true);
    expect(commandStateFor("audioReady").isTranscribing).toBe(false);
    expect(commandStateFor("scoreReady").hasScore).toBe(true);
    expect(commandStateFor("reviewing").hasScore).toBe(true);
    expect(commandStateFor("reviewing").reviewOpen).toBe(true);
    expect(commandStateFor("audioReady").hasScore).toBe(false);
  });
});

import type { CommandSnapshot } from "../commands/types";

/**
 * Workspace screen state machine (docs/GUI_UX_SPEC.md §27).
 *
 * The shell owns *which regions exist* for each state; feature code owns the
 * transitions (open audio → audioReady, transcribe → transcribing, …).
 * UI-020 added the import-side states (issue #25: EMPTY / OPENING_AUDIO /
 * AUDIO_READY / AUDIO_ERROR / SOURCE_MISSING).
 *
 *   EMPTY ─open→ OPENING_AUDIO ─ok→ AUDIO_READY ─transcribe→ TRANSCRIBING
 *                     │                                     ├ cancel → AUDIO_READY
 *                     ├ bad format/read → AUDIO_ERROR ─閉じる→ EMPTY
 *                     └ source moved → SOURCE_MISSING ─relink ok→ AUDIO_READY
 *                                            └ hash mismatch → SOURCE_MISSING
 *                                                       TRANSCRIBING
 *                                          ├ fail   → TRANSCRIPTION_ERROR
 *                                          └ done   → SCORE_READY
 *   TRANSCRIPTION_ERROR ─dismiss/retry→ last valid state (audioReady or
 *   scoreReady — a prior score is never destroyed by a failed job).
 *   SCORE_READY ├ review → REVIEWING ├ export → EXPORTING └ retranscribe
 */
export type ScreenState =
  | "empty"
  | "openingAudio"
  | "audioReady"
  | "audioError"
  | "sourceMissing"
  | "transcribing"
  // [UI-040] §27 TRANSCRIPTION_ERROR — job failed / worker crash or
  // unresponsive mid-job. A loaded state (audio/score state is kept).
  | "transcriptionError"
  | "scoreReady"
  | "reviewing"
  | "exporting";

export const SCREEN_STATES: readonly ScreenState[] = [
  "empty",
  "openingAudio",
  "audioReady",
  "audioError",
  "sourceMissing",
  "transcribing",
  "transcriptionError",
  "scoreReady",
  "reviewing",
  "exporting",
];

/**
 * Region visibility per state (§3 empty state shows none of the work
 * surfaces; §4+ show all once audio exists).
 */
export interface RegionVisibility {
  /** Waveform / timeline strip. */
  waveform: boolean;
  /** Score workspace region — always mounted (it carries the empty state). */
  score: boolean;
  /** Properties panel region — also gated by the user close/open toggle. */
  properties: boolean;
  /** Transport bar. */
  transport: boolean;
}

/**
 * Whether the workspace chrome exists for this state (waveform strip and,
 * once loaded, transport/properties). EMPTY and the two import error
 * states show only the centered score-region surface (§3, §20);
 * OPENING_AUDIO already mounts the waveform strip so the loading line has
 * its final home (loading.openingAudio → waveform.loading).
 */
export function hasWorkspaceRegions(screen: ScreenState): boolean {
  return (
    screen !== "empty" && screen !== "audioError" && screen !== "sourceMissing"
  );
}

export function regionVisibility(screen: ScreenState): RegionVisibility {
  const context = hasWorkspaceRegions(screen);
  const loaded = context && screen !== "openingAudio";
  return {
    waveform: context,
    score: true,
    // The panel itself decides open/closed; EMPTY never mounts it (§3), and
    // it stays hidden while the file is still opening.
    properties: loaded,
    transport: loaded,
  };
}

/**
 * Map the screen machine onto the UI-012 CommandSnapshot fields (§23) so
 * command enablement stays consistent: 採譜 needs audio and is disabled
 * while a transcription runs (§5), 要確認 needs a score with pending
 * issues, 書き出し needs a score. Playback/undo/selection fields are owned
 * by their feature issues, not by the screen machine.
 */
export function commandStateFor(
  screen: ScreenState,
): Pick<
  CommandSnapshot,
  "hasAudio" | "hasScore" | "isTranscribing" | "reviewOpen"
> {
  const hasScore =
    screen === "scoreReady" || screen === "reviewing" || screen === "exporting";
  return {
    // Audio-gated commands stay off while the file is still opening and in
    // the error states — nothing playable exists yet.
    hasAudio: hasWorkspaceRegions(screen) && screen !== "openingAudio",
    hasScore,
    isTranscribing: screen === "transcribing",
    reviewOpen: screen === "reviewing",
  };
  // [UI-040] transcriptionError: hasAudio=true (loaded), isTranscribing
  // =false → 採譜 stays reachable as the retry path; hasScore=false keeps
  // score/export commands off while the §20 error surface is up.
}
